x=result('long-string-comment.step');assert x['status']==1 and x['recordCount']==12 and x['entityCount']==2;assert next(q for q in x['canonical']if q['id']=='#1')['args'][0]['length']==12191
summary={'scope':r['scope'],'fourVariants':variants,'corpusInputs':18,'pairedEofInputs':8,'pairedActualStreamErrors':8,'totalConfigurations':34,'totalReadStreamCalls':136,'allFieldsEquivalent':r['allEquivalent'],'explicitCanonicalAssertions':['empty and nested list subrecord structure/order','typed LENGTH_MEASURE value 1.25','ordered misc/void/enum/ident/text/integer/real values','complex entity component order','error recovery preserves later #3 after entity','12191-byte multi-line quoted string survives cross-8192 read with trailing entity'],'faultEvidence':{'allActualFaultsTriggered':True,'ReadStreamStatus':3,'statusName':'IFSelect_RetFail','scanner':{'bad':True,'fail':True,'eof':False},'caller':{'bad':False,'fail':False,'eof':False},'escapedException':''},'sourceHash':r['sha256'],'limitations':['Noncryptographic dual 64-bit rolling digests; complete raw strings/lengths/enums/order are hashed, not bounded prefixes.','Bounded canonical capture max 64 records /32768 bytes/value prefix256; truncated capture may be a string prefix rather than valid JSON.','entityLoadObservations contains duplicate observations from matching a neighboring commented example; it is not an entity count. Final modelEntityDigest and entityCount traverse actual model.Value(1..N) independently.','Unknown TEST_ENTITY cases exercise raw parser/unknown entity preservation, not full schema semantic validity.','Error/recovery agreement with original does not establish full ISO 10303 correctness; seed digests on parser rejection are not nonempty semantic evidence.','No native transfer/meshing geometry equivalence or performance conclusions are derived from this parse-only diagnostic.'],'corpus':[]}
for row in small:
 x=row['results']['original'];summary['corpus'].append({'name':row['name'],'bytes':row['bytes'],**{k:x[k]for k in ['status','recordCount','argumentCount','entityCount','rawDigest','modelEntityDigest','canonicalTruncated']}})
